import { button, badge, emptyState, escapeHtml as e } from "./ui.js";
import { canPublish } from "./access.js";
import { icon } from "./icons.js";
import { subjects } from "./network-analytics.js";
import { demoDate } from "./chairman-data.js";
import { panel, metric, select, table, sparkline } from "./chairman.js";
import { coursesPage } from "./learning.js";
import { sectionCourseProgress } from "./section-data.js";
import { sectionReportPreview } from "./section-head.js";
import { classViews, classReportTypes, classScope, classAcademic, classAttendance, classCourses, classStudents, classGuardians, classStudentProgress,
  classOverview, classFollowups, classTaskStatuses, classAttendanceStatuses, classDiscussionNotes, classSupportRequests, classSupportTypes, visibleClassReports } from "./class-data.js";

const pct = (value) => Number(value).toFixed(1) + "%";
const mark = (row) => row.count ? pct(row.mean) : "—";
const choices = (values, current) => values.map(([id, name]) => `<option value="${e(id)}" ${String(id) === String(current) ? "selected" : ""}>${e(name)}</option>`).join("");
const heading = (title, text, actions = "") => `<header class="chairman-page-heading"><div><h1>${title}</h1><p>${text}</p></div><div class="chairman-heading-actions">${badge("Sample data", "amber")}${actions}</div></header>`;
const footer = (label) => `<p class="form-error" role="alert" hidden></p><footer class="dialog-actions">${button("Cancel", "close-dialog", { variant: "secondary" })}<button class="button primary" type="submit">${label}</button></footer>`;
const link = (view, text) => `<a class="button secondary compact" href="#class_teacher/overview/${view}">${text}</a>`;
const history = (notes, title) => notes?.length ? `<div class="vice-note-history"><h3>${title}</h3>${notes.map((note) => `<article><p>${e(note.text)}</p><small>${e(note.by)} · ${e(note.at.slice(0, 10))}</small></article>`).join("")}</div>` : "";

function identity(options, scope) {
  const entries = options.state.accounts.flatMap((person) => person.grants.map((grant, index) => ({ person, grant, index }))).filter(({ grant }) => grant.role === "class_teacher");
  const selected = options.context.account.id + "|" + options.context.account.grants.indexOf(options.context.grant);
  return `<header class="section-identity"><div><span class="chairman-eyebrow">CLASS TEACHER WORKSPACE</span><h1>Class ${e(scope.className)}</h1><p>${e(scope.branch.school)} · Grade ${scope.grade} · ${e(scope.section.name)}</p></div><label class="principal-demo-account"><span>Demo Class Teacher</span><span class="select-wrap"><select data-change="account" aria-label="Preview Class Teacher">${choices(entries.map(({ person, grant, index }) => [person.id + "|" + index, person.name + " · " + options.state.branches.find((branch) => branch.id === grant.branch)?.name + " · " + grant.className]), selected)}</select>${icon("chevronDown", 14)}</span></label></header>`;
}
function filters(options, scope, kind) {
  const f = options.classTeacher;
  return `<div class="chairman-filters"><div class="grade-fixed-scope">${icon("school", 18)}<div><small>Assigned class</small><strong>Class ${e(scope.className)}</strong></div></div>${["learning", "reports"].includes(kind) ? select("Assessment term", "class-term", [1, 2, 3].map((term) => [term, "Term " + term]), f.term) : ""}${kind === "reports" ? select("Brief summary subject", "class-subject", subjects.map((subject) => [subject.id, subject.name]), f.subject) : ""}${["attendance", "reports"].includes(kind) ? `<label class="chairman-filter"><span>Reporting date</span><input type="date" aria-label="Reporting date" data-change="class-date" min="2026-10-12" max="${demoDate}" value="${f.date}"></label>` + select("Attendance period", "class-period", [["day", "One school day"], ["week", "Last 5 school days"], ["month", "Last 20 school days"]], f.period) : ""}</div>`;
}
function followups(options) {
  const items = classFollowups(options.state, options.context);
  return panel("Class attendance follow-ups", "Your class register concerns, due dates and note history", items.length ? table(["Student", "Owner", "Due", "Status", "Action"], items.map((item) => `<tr><td><strong>${e(item.name)}</strong><small>${e(item.admission)} · Class ${e(item.className)}</small></td><td>${e(item.owner)}</td><td>${e(item.due)}</td><td>${badge(classTaskStatuses[item.status], item.status === "resolved" ? "green" : "amber")}</td><td>${button("Update follow-up", "class-followup-edit", { value: item.id, variant: "secondary compact" })}</td></tr>`).join(""), "Class follow-ups") : emptyState("checkCircle", "No attendance follow-ups recorded", "Open a sample student in Attendance to record a follow-up."));
}
function subjectTable(result) {
  return table(["Subject", "Class average", "Pass rate", "Sample assessed"], result.rows.map((row) => `<tr><td>${e(row.name)}</td><td>${mark(row)}</td><td>${row.count ? pct(row.passRate) : "—"}</td><td>${row.count}</td></tr>`).join(""), "Class subject comparison");
}
function overview(options) {
  const data = classOverview(options.state, options.context);
  return heading("Class Overview", "Daily class readiness, attendance and student learning progress.", link("learning", "Review learning")) + `<div class="chairman-metrics">${metric("Sample class attendance", data.attendance.summary.expected ? pct(data.attendance.summary.rate) : "—", "20 Nov · Your class register", "checkCircle")}${metric("Registered students", data.registered, "Actual prototype admission records", "users", "blue")}${metric("Class courses", data.courses.length, "Course and teacher assignments are read-only", "book")}${metric("Pending follow-ups", data.followups.filter((item) => item.status !== "resolved").length, "Recorded class attendance concerns", "clock", "amber")}</div>` +
    `<div class="section-summary-strip"><div><span>Register entries marked</span><strong>${data.attendance.marked} / ${data.attendance.roster.length}</strong></div><div><span>Published materials</span><strong>${data.materials}</strong></div><div><span>Materials marked done</span><strong>${data.completed} / ${data.expected}</strong></div><div><span>Coordinator requests open</span><strong>${data.requests.filter((item) => item.status !== "resolved").length}</strong></div></div><div class="section-attention"><div><h2>Class priorities</h2><p>${data.attendance.marked ? "Saved attendance entries overlay the generated sample register." : "The illustrative register is ready for you to mark."} ${data.discussions.filter((item) => item.status === "planned").length} parent discussions planned.</p></div>${link("attendance", "Open register")}</div>` +
    `<div class="chairman-two-columns">${panel("Class subject results", "Term 3 illustrative assessments · This class only", subjectTable(data.academic))}${panel("Five-day attendance trend", "Includes saved class-register entries · Late counts as present", sparkline(classAttendance(options.state, options.context, { period: "week" }).trend, "Class attendance trend"))}</div>` + followups(options);
}
function learning(options, scope) {
  const courses = classCourses(options.state, options.context);
  if (courses.some((course) => course.id === options.courseId)) return coursesPage(options);
  const progress = courses.map((course) => sectionCourseProgress(options.state, course));
  const rows = courses.map((course) => { const p = sectionCourseProgress(options.state, course), publishing = canPublish(options.state, options.context, course); return `<tr><td><strong>${e(course.title)}</strong><small>Class ${e(course.className)}</small></td><td>${e(p.teacher)}</td><td>${p.enrolled}</td><td>${p.materials}</td><td>${p.completed} / ${p.expected}</td><td><div class="section-row-actions">${button("Materials & progress", "open-course", { value: course.id, variant: "secondary compact" })}${publishing ? button("Add material", "add-material", { value: course.id, variant: "secondary compact", iconName: "plus" }) : badge("Read access", "neutral")}</div></td></tr>`; }).join("");
  return heading("Learning & Materials", "Review every subject in your class; publish only on courses assigned to you.") + filters(options, scope, "learning") + `<div class="chairman-metrics">${metric("Class courses", courses.length, "Existing course assignments", "book")}${metric("Lecture materials", progress.reduce((sum, p) => sum + p.materials, 0), "Published class materials", "file", "blue")}${metric("Materials marked done", progress.reduce((sum, p) => sum + p.completed, 0) + " / " + progress.reduce((sum, p) => sum + p.expected, 0), "Completion recorded in the parent portal", "checkCircle")}${metric("Your teaching courses", courses.filter((course) => canPublish(options.state, options.context, course)).length, "Publication follows the assigned teacher", "users", "amber")}</div>` +
    panel("Class courses and lecture progress", "Teacher assignment and student enrolment remain with academic leadership", courses.length ? table(["Course", "Assigned teacher", "Enrolled", "Materials", "Done / assigned", "Actions"], rows, "Class courses") : emptyState("book", "No courses assigned to this class", "Leadership can assign existing courses to students in this class.")) + panel("Subject comparison", "Illustrative assessments for the selected term · This class only", subjectTable(classAcademic(options.state, options.context, options.classTeacher)));
}
function attendance(options, scope) {
  const f = options.classTeacher, result = classAttendance(options.state, options.context, f), page = Math.min(f.page, Math.max(1, Math.ceil(result.rows.length / 12))), start = (page - 1) * 12;
  return heading("Attendance", "Mark the illustrative class register and follow up absences or late arrivals.", result.roster.length ? button("Mark class attendance", "class-mark-attendance", { value: "", iconName: "edit" }) : "") + filters(options, scope, "attendance") +
    `<div class="class-register-state"><div><strong>${result.marked} of ${result.roster.length} entries marked for ${result.last}</strong><p>Saved entries are reflected in Grade Coordinator, Section Head and leadership views. Unmarked students use generated sample attendance.</p></div>${result.marked ? button("Restore generated sample", "class-reset-attendance", { value: result.last, variant: "secondary compact" }) : badge("Illustrative register", "amber")}</div><p class="chairman-filter-note">${result.dates[0]} – ${result.last} · ${result.dates.length} school day(s). Marking applies to the latest school day shown. Period totals count attendance-days; late arrivals count as present.</p>` +
    `<div class="chairman-metrics">${metric("Attendance rate", result.summary.expected ? pct(result.summary.rate) : "—", "Your class only", "checkCircle")}${metric("Present", result.summary.present, "Out of " + result.summary.expected + " expected attendance-days", "users", "blue")}${metric("Absent", result.summary.absent, "Selected school-day period", "alert", "amber")}${metric("Late arrivals", result.summary.late, "Included in present totals", "clock")}</div>` + panel("Class register", "Illustrative attendance students are separate from the actual admission records in Student Support", `<div class="chairman-list-tools">${select("Attendance watchlist", "class-flag", [["all", "All class students"], ["repeated", "3+ absences in 20 days"], ["absent", "Absent on latest day"], ["late", "Late on latest day"]], f.flag)}<label class="chairman-search">${icon("search", 16)}<input type="search" aria-label="Search class register" data-change="class-query" data-focus="class-search" value="${e(f.query)}" placeholder="Search sample student or admission"></label></div>` +
    table(["Sample student", "Absences in 20 days", "Latest status", "Action"], result.rows.slice(start, start + 12).map((student) => `<tr><td><button class="chairman-person-link" type="button" data-action="class-student" data-value="${student.id}">${e(student.name)}</button><small>${e(student.admission)}</small></td><td>${student.missed}</td><td>${badge(classAttendanceStatuses[student.status], student.status === "present" ? "green" : "amber")}</td><td>${button("Update attendance", "class-mark-attendance", { value: student.id, variant: "secondary compact" })}</td></tr>`).join(""), "Class student register") + `<div class="chairman-pager"><span>${result.rows.length ? start + 1 : 0}–${Math.min(start + 12, result.rows.length)} of ${result.rows.length}</span><div>${button("Previous", "class-page", { value: page - 1, variant: "secondary compact", extra: page <= 1 ? "disabled" : "" })}<span>Page ${page}</span>${button("Next", "class-page", { value: page + 1, variant: "secondary compact", extra: start + 12 >= result.rows.length ? "disabled" : "" })}</div></div>`, button("Register CSV", "class-export", { value: "attendance", variant: "secondary compact", iconName: "download" })) + panel("Attendance trend", "Includes saved sample-register entries for this class", sparkline(result.trend, "Selected class attendance trend")) + followups(options);
}
function support(options) {
  const students = classStudents(options.state, options.context), discussions = classDiscussionNotes(options.state, options.context), requests = classSupportRequests(options.state, options.context);
  const rows = students.map((student) => { const p = classStudentProgress(options.state, options.context, student), guardians = classGuardians(options.state, options.context, student); return `<tr><td><strong>${e(student.name)}</strong><small>${e(student.admissionNumber)}</small></td><td>${guardians.map((person) => e(person.name)).join(", ") || "No linked guardian"}</td><td>${p.courses}</td><td>${p.completed} / ${p.materials}</td><td>${button("Record parent discussion", "class-discussion-new", { value: student.id, variant: "secondary compact" })}</td></tr>`; }).join("");
  return heading("Student Support", "Review your actual class students, record discussion notes and coordinate support.", button("Request coordinator support", "class-support", { value: "", variant: "secondary", iconName: "plus" })) +
    `<div class="chairman-metrics">${metric("Actual class students", students.length, "Prototype admission records", "users")}${metric("Parent discussions planned", discussions.filter((item) => item.status === "planned").length, "Private local Class Teacher records", "calendar", "blue")}${metric("Attendance follow-ups open", classFollowups(options.state, options.context).filter((item) => item.status !== "resolved").length, "Separate illustrative register concerns", "clock", "amber")}${metric("Coordinator requests open", requests.filter((item) => item.status !== "resolved").length, "School and grade queue only", "book")}</div>` +
    panel("Students and linked guardians", "Actual prototype enrolment/completion records · Admission and guardian assignments are read-only", students.length ? table(["Student", "Linked guardians", "Courses", "Materials done / assigned", "Action"], rows, "Class actual students") : emptyState("users", "No admission records in this class", "The illustrative attendance register does not create actual student admissions.")) +
    panel("Parent discussion records", "Local planning/outcome notes only · No contact details are invented and no messages are sent", discussions.length ? `<div class="grade-support-grid">${discussions.map((item) => `<article class="grade-support-card class-discussion-card"><div>${badge(item.status === "planned" ? "Planned" : "Completed", item.status === "completed" ? "green" : "amber")}<small>${e(item.date)}</small></div><h3>${e(item.name)}</h3><small>${e(item.guardianName)}</small><p>${e(item.note)}</p>${button("Update discussion", "class-discussion-edit", { value: item.id, variant: "secondary compact" })}</article>`).join("")}</div>` : emptyState("users", "No discussion records yet", "Record a planned or completed parent discussion against an actual student.")) +
    panel("Grade Coordinator requests and responses", "Requests and responses stay in the current browser; a response does not allocate cover or change course assignments", `<div class="grade-support-grid">${requests.map((item) => `<article class="grade-support-card"><div>${badge(classSupportTypes[item.type], "blue")}${badge(classTaskStatuses[item.status], item.status === "resolved" ? "green" : "amber")}</div><h3>${e(item.title)}</h3><p>${e(item.note)}</p>${item.responses?.length ? `<div class="grade-response"><strong>Grade Coordinator response</strong>${item.responses.map((response) => `<p>${e(response.text)}</p><small>${e(response.by)} · ${e(response.at.slice(0, 10))}</small>`).join("")}</div>` : '<p class="chairman-filter-note">Awaiting Grade Coordinator review</p>'}</article>`).join("") || emptyState("checkCircle", "No support requested", "Use Request coordinator support to record a class or course concern.")}</div>`) + followups(options);
}
function reports(options, scope) {
  const f = options.classTeacher, reports = visibleClassReports(options.state, options.context), current = reports.find((report) => report.id === f.reportId);
  return heading("Class Reports", "Capture class learning, attendance and follow-up progress for your academic leadership.") + `<div class="section-report-builder surface"><div>${select("Report type", "class-report-type", Object.entries(classReportTypes), f.reportType)}</div>${filters(options, scope, "reports")}<div class="section-report-generate"><p>${icon("school", 17)}${e(scope.branch.name)} · Class ${e(scope.className)} only</p>${button("Generate class report", "class-generate-report", { iconName: "file" })}</div></div><section class="surface chairman-report-result"><div class="chairman-report-actions">${current ? select("Download format", "class-report-format", [["csv", "CSV spreadsheet"], ["html", "Standalone HTML"]], f.reportFormat) + button("Download report", "class-download-report", { value: current.id, variant: "secondary", iconName: "download" }) + button("Print / Save PDF", "class-print-report", { value: current.id, variant: "secondary", iconName: "file" }) : "Report preview"}</div>${current ? sectionReportPreview(current) : emptyState("file", "Your class report starts here", "Choose a report and filters, then generate a snapshot. Private parent-discussion notes are excluded.")}</section>` +
    panel("Saved class snapshots", "Latest eight per school/grade/class · Separate from other classes and leadership reports", `<div class="chairman-report-history">${reports.map((item) => `<button type="button" class="chairman-history-card ${item.id === current?.id ? "is-selected" : ""}" data-action="class-open-report" data-value="${item.id}">${icon("file", 20)}<span><strong>${e(item.title)}</strong><small>Class ${e(scope.className)} · ${e(item.criteria.to)} · ${item.customRows.length} rows</small></span>${badge("Sample", "neutral")}</button>`).join("") || '<p class="chairman-no-history">Generated class reports will appear here.</p>'}</div>`);
}

export function classTeacherPage(options) {
  const scope = classScope(options.state, options.context);
  if (!scope) return emptyState("school", "No class assigned", "A Class Teacher appointment with a school, grade and class is required.");
  const view = options.classTeacher.view;
  return `<section class="chairman-portal section-portal class-teacher-portal">${identity(options, scope)}<nav class="chairman-view-bar section-view-bar" aria-label="Class Teacher views">${classViews.map((item) => `<a href="#class_teacher/overview/${item.id}" aria-label="${item.name}" ${item.id === view ? 'aria-current="page" class="is-active"' : ""}>${icon(item.icon, 18)}<span class="chairman-view-full">${item.name}</span><span class="chairman-view-short">${item.short}</span></a>`).join("")}</nav><div class="chairman-analytics section-analytics">${({ summary: overview, learning, attendance, support, reports })[view](options, scope)}</div></section>`;
}

export function classAttendanceForm(options, studentId = "") {
  const result = classAttendance(options.state, options.context, options.classTeacher), roster = studentId ? result.roster.filter((student) => student.id === studentId) : result.roster;
  return `<form data-form="class-attendance"><div class="form-body"><input type="hidden" name="date" value="${result.last}"><p class="chairman-filter-note">Illustrative class register · ${result.last}. Saved statuses update related leadership totals. Late arrivals count as present.</p><div class="class-attendance-inputs">${roster.map((student) => `<label class="field"><span>${e(student.name)}<small>${e(student.admission)}</small></span><input type="hidden" name="student" value="${student.id}"><select name="status_${student.id}" aria-label="Attendance for ${e(student.name)}">${choices(Object.entries(classAttendanceStatuses), student.status)}</select></label>`).join("")}</div></div>${footer("Save class attendance")}</form>`;
}
export function classFollowupForm(student, previous) {
  return `<form data-form="class-followup"><div class="form-body"><input type="hidden" name="id" value="${e(previous?.id || "")}"><input type="hidden" name="student" value="${e(student.id)}"><h3>${e(student.name)} · Class ${e(student.className)}</h3><label class="field">Follow-up status<select name="status">${choices(Object.entries(classTaskStatuses), previous?.status || "open")}</select></label><label class="field">Due date<input name="due" type="date" min="${demoDate}" max="2026-11-27" value="${e(previous?.due || demoDate)}" required></label><label class="field">Follow-up note<textarea name="note" rows="3" maxlength="1000" required></textarea></label>${history(previous?.notes, "Previous follow-up notes")}<p class="chairman-filter-note">The active Class Teacher is recorded as the follow-up owner.</p></div>${footer("Save class follow-up")}</form>`;
}
export function classDiscussionForm(options, student, previous) {
  const guardians = classGuardians(options.state, options.context, student);
  return `<form data-form="class-discussion"><div class="form-body"><input type="hidden" name="id" value="${e(previous?.id || "")}"><input type="hidden" name="student" value="${e(student.id)}"><h3>${e(student.name)}</h3><p class="chairman-filter-note">${e(student.admissionNumber)} · Class ${e(student.className)}</p><label class="field">Linked guardian<select name="guardian">${choices([["", "No linked guardian selected"], ...guardians.map((person) => [person.id, person.name])], previous ? previous.guardian : guardians[0]?.id || "")}</select></label><label class="field">Discussion date<input name="date" type="date" min="${demoDate}" max="2026-11-27" value="${e(previous?.date || demoDate)}" required></label><label class="field">Discussion status<select name="status">${choices([["planned", "Planned"], ["completed", "Completed"]], previous?.status || "planned")}</select></label><label class="field">Discussion note<textarea name="note" rows="3" maxlength="1000" required placeholder="Record the plan or meeting outcome"></textarea></label>${history(previous?.notes, "Previous discussion notes")}<p class="chairman-filter-note">Private local class record. This does not contact the guardian or appear in parent portals or report exports.</p></div>${footer("Save discussion record")}</form>`;
}
